import java.util.Arrays; class Solution { public int maxEnvelopes(int[][] envelopes) { if (envelopes == null || envelopes.length == 0) return 0; Arrays.sort(envelopes, (a, b) -> { if (a[0] != b[0]) return Integer.compare(a[0], b[0]); return Integer.compare(b[1], a[1]); }); int[] tails = new int[envelopes.length]; int size = 0; for (int[] envelope : envelopes) { int h = envelope[1]; int i = 0, j = size; while (i < j) { int m = i + (j - i) / 2; if (tails[m] < h) i = m + 1; else j = m; } tails[i] = h; if (i == size) size++; } return size; } }